using Voytek.Domain.Tenancy;
namespace Voytek.Domain.Approvals;
public sealed class ApprovalRequest : ITenantScoped
{ private ApprovalRequest(){} public ApprovalRequest(Guid id,Guid tenantId,Guid authorizationRequestId,DateTimeOffset now){Id=id;TenantId=tenantId;AuthorizationRequestId=authorizationRequestId;Status=ApprovalStatus.Pending;CreatedAtUtc=now;} public Guid Id{get;private set;} public Guid TenantId{get;set;} public Guid AuthorizationRequestId{get;private set;} public ApprovalStatus Status{get;private set;} public Guid? DecidedByUserId{get;private set;} public DateTimeOffset CreatedAtUtc{get;private set;} public DateTimeOffset? DecidedAtUtc{get;private set;} public void Approve(Guid userId,DateTimeOffset now){if(Status!=ApprovalStatus.Pending)throw new InvalidOperationException("Only pending approvals can be approved.");Status=ApprovalStatus.Approved;DecidedByUserId=userId;DecidedAtUtc=now;} public void Reject(Guid userId,DateTimeOffset now){if(Status!=ApprovalStatus.Pending)throw new InvalidOperationException("Only pending approvals can be rejected.");Status=ApprovalStatus.Rejected;DecidedByUserId=userId;DecidedAtUtc=now;} }
